import { bySlug, LOCALES, type Exercise } from '../../content/schema/exercise.ts';
import type { Programme } from '../../content/schema/programme.ts';
import { programmeSql } from './programme-sql.ts';
import { array, bool, jsonb, literal, nullable } from './sql.ts';

// ADR 0005: the content seed is generated SQL. It is idempotent (upserts by slug), runs in one transaction
// and never deletes an exercise (PRD §11: referenced exercises are unpublished, not removed).

export const SEED_HEADER = [
  '-- GENERATED by `pnpm seed:generate` from content/ (ADR 0005). Do not edit by hand.',
  '-- Idempotent: safe to apply more than once.',
].join('\n');

const rows = (lines: string[]) => lines.map((line) => `  ${line}`).join(',\n');

function exercisesSql(exercises: readonly Exercise[]): string {
  const values = exercises.map((e) =>
    [
      `(${literal(e.slug)}`,
      `${literal(e.category)}::public.exercise_category`,
      `${nullable(e.pattern)}::public.exercise_pattern`,
      `${literal(e.difficulty)}::public.difficulty_level`,
      array(e.equipment, 'public.equipment_type'),
      array(e.muscleGroups, 'text'),
      bool(e.isUnilateral),
      `${literal(e.slug)})`,
    ].join(', '),
  );
  return [
    'insert into public.exercises',
    '  (slug, category, pattern, difficulty, equipment, muscle_groups, is_unilateral, media_key)',
    'values',
    rows(values),
    'on conflict (slug) do update set',
    '  category = excluded.category,',
    '  pattern = excluded.pattern,',
    '  difficulty = excluded.difficulty,',
    '  equipment = excluded.equipment,',
    '  muscle_groups = excluded.muscle_groups,',
    '  is_unilateral = excluded.is_unilateral,',
    '  media_key = excluded.media_key;',
  ].join('\n');
}

function translationsSql(exercises: readonly Exercise[]): string {
  const values = exercises.flatMap((e) =>
    LOCALES.map((locale) => {
      const t = e[locale];
      return [
        `(${literal(e.slug)}`,
        `${literal(locale)}::public.app_locale`,
        literal(t.name),
        array(t.altNames, 'text'),
        literal(t.description),
        jsonb(t.instructions),
        jsonb(t.commonMistakes),
        `${literal(t.mediaAlt)})`,
      ].join(', ');
    }),
  );
  return [
    'insert into public.exercise_translations',
    '  (exercise_id, locale, name, alt_names, description, instructions, common_mistakes, media_alt)',
    'select e.id, v.locale, v.name, v.alt_names, v.description, v.instructions, v.common_mistakes, v.media_alt',
    'from (values',
    rows(values),
    ') as v (slug, locale, name, alt_names, description, instructions, common_mistakes, media_alt)',
    'join public.exercises e on e.slug = v.slug',
    'on conflict (exercise_id, locale) do update set',
    '  name = excluded.name,',
    '  alt_names = excluded.alt_names,',
    '  description = excluded.description,',
    '  instructions = excluded.instructions,',
    '  common_mistakes = excluded.common_mistakes,',
    '  media_alt = excluded.media_alt;',
  ].join('\n');
}

function relationsSql(exercises: readonly Exercise[]): string {
  const slugs = exercises.map((e) => literal(e.slug)).join(', ');
  const relations = exercises.flatMap((e) => [
    ...[...e.relations.variations].sort().map((r) => [e.slug, r, 'variation'] as const),
    ...[...e.relations.substitutes].sort().map((r) => [e.slug, r, 'substitute'] as const),
  ]);
  // Relations are rebuilt from content; no history row references them.
  const statements = [
    'delete from public.exercise_relations',
    `where exercise_id in (select id from public.exercises where slug in (${slugs}));`,
  ];
  if (relations.length > 0) {
    statements.push(
      '',
      'insert into public.exercise_relations (exercise_id, related_exercise_id, kind)',
      'select a.id, b.id, v.kind',
      'from (values',
      rows(
        relations.map(
          ([from, to, kind]) =>
            `(${literal(from)}, ${literal(to)}, ${literal(kind)}::public.exercise_relation_kind)`,
        ),
      ),
      ') as v (slug, related_slug, kind)',
      'join public.exercises a on a.slug = v.slug',
      'join public.exercises b on b.slug = v.related_slug;',
    );
  }
  return statements.join('\n');
}

/**
 * Builds the seed from validated content (see `checkLibrary` and `checkProgrammes`).
 * Same input, same output, byte for byte.
 */
export function buildSeed(
  exercises: readonly Exercise[],
  programmes: readonly Programme[] = [],
): string {
  if (exercises.length === 0) throw new RangeError('The seed needs at least one exercise');
  const sorted = [...exercises].sort(bySlug);
  const programmeSections = [...programmes]
    .sort((a, b) => bySlug(a, b) || a.version - b.version)
    .flatMap((p) => [
      '',
      `-- Programme ${p.slug} v${p.version} (PRD §7, ADR 0004)`,
      programmeSql(p),
    ]);
  return [
    SEED_HEADER,
    '',
    'begin;',
    '',
    '-- Exercises (PRD §8, §11)',
    exercisesSql(sorted),
    '',
    '-- Exercise translations (D15)',
    translationsSql(sorted),
    '',
    '-- Variations and substitutes',
    relationsSql(sorted),
    ...programmeSections,
    '',
    'commit;',
    '',
  ].join('\n');
}
